// orientation(...) returns 1, -1, or 0 as defined in the orientation topic
bool segmentsIntersect(Point p1, Point p2, Point p3, Point p4) {
    int d1 = orientation(p3, p4, p1);
    int d2 = orientation(p3, p4, p2);
    int d3 = orientation(p1, p2, p3);
    int d4 = orientation(p1, p2, p4);
    return d1 != d2 && d3 != d4;   // each segment straddles the other
}

